<script setup>
import{ref,onMounted,computed}from'vue';import{api}from'../services/api.js';import{can,auth}from'../stores/auth.js';import BaseModal from'../components/BaseModal.vue';import UiState from'../components/UiState.vue'
const emptyForm=()=>({name:'',username:'',email:'',role_id:'',password:'',is_active:true,time_clock_code:null,multi_time_clock_enabled:false,time_clock_day_night_columns_enabled:false,time_clock_management_enabled:false,parent_user_id:null,overtime_base_minutes:480,overtime_half_threshold_minutes:25,overtime_full_threshold_minutes:55})
const users=ref([]),roles=ref([]),search=ref(''),loading=ref(true),error=ref(''),open=ref(false),saving=ref(false),editing=ref(null),form=ref(emptyForm())
const supervisor=computed(()=>['Administrador','Supervisor'].includes(auth.user.role_name))
async function load(){loading.value=true;error.value='';try{const [u,r]=await Promise.all([api.get('/users?limit=100&search='+encodeURIComponent(search.value)),api.get('/roles')]);users.value=u.items;roles.value=r}catch(e){error.value=e.message}finally{loading.value=false}}
function edit(u){editing.value=u;form.value={...emptyForm(),...u,password:'',is_active:!!u.is_active,parent_user_id:u.parent_user_id||null};open.value=true}
function create(){editing.value=null;form.value={...emptyForm(),role_id:roles.value[0]?.id||''};open.value=true}
async function save(){saving.value=true;error.value='';try{const result=editing.value?(await api.put('/users/'+editing.value.id,form.value),{id:editing.value.id}):await api.post('/users',form.value);if(supervisor.value)await api.patch(`/users/${result.id}/time-clock`,{time_clock_code:form.value.time_clock_code||null,multi_time_clock_enabled:form.value.multi_time_clock_enabled,time_clock_day_night_columns_enabled:form.value.time_clock_day_night_columns_enabled,time_clock_management_enabled:form.value.time_clock_management_enabled,parent_user_id:form.value.parent_user_id||null,overtime_base_minutes:form.value.overtime_base_minutes,overtime_half_threshold_minutes:form.value.overtime_half_threshold_minutes,overtime_full_threshold_minutes:form.value.overtime_full_threshold_minutes});open.value=false;await load()}catch(e){error.value=e.message}finally{saving.value=false}}
onMounted(load)
</script>
<template><div class="toolbar"><label class="search"><span class="sr-only">Cercar usuaris</span><input v-model="search" placeholder="Cercar per nom, usuari o correu…" @keyup.enter="load"><button class="button secondary" @click="load">Cercar</button></label><button v-if="can('users.manage')" class="button primary" @click="create">Nou usuari</button></div>
<UiState :loading="loading" :error="error" :empty="!users.length" empty-text="No s’han trobat usuaris."><div class="table-wrap"><table><thead><tr><th>Usuari</th><th>Rol</th><th>Fitxatge</th><th>Estat</th><th>Últim accés</th><th></th></tr></thead><tbody><tr v-for="u in users" :key="u.id"><td><strong>{{u.name}}</strong><small>@{{u.username}} · {{u.email}}</small></td><td>{{u.role_name}}</td><td>{{u.time_clock_code||'Sense codi'}}</td><td><span class="badge" :class="u.is_active?'success':'neutral'">{{u.is_active?'Actiu':'Inactiu'}}</span></td><td>{{u.last_login_at?new Date(u.last_login_at).toLocaleString('ca-ES'):'Mai'}}</td><td><button v-if="can('users.manage')" class="button secondary compact" @click="edit(u)">Editar</button></td></tr></tbody></table></div></UiState>
<BaseModal :open="open" :title="editing?'Editar usuari':'Crear usuari'" @close="open=false"><form id="user-form" class="form-grid" @submit.prevent="save"><label>Nom<input v-model="form.name" required maxlength="120"></label><label>Nom d’usuari<input v-model="form.username" required maxlength="80" pattern="[A-Za-z0-9._-]+"></label><label>Correu electrònic<input v-model="form.email" type="email" required></label><label>Rol<select v-model="form.role_id" required><option v-for="r in roles" :key="r.id" :value="r.id">{{r.name}}</option></select></label><label>Contrasenya {{editing?'(buida per conservar-la)':''}}<input v-model="form.password" type="password" :required="!editing" minlength="1"></label><label class="check"><input v-model="form.is_active" type="checkbox"> Usuari actiu</label>
<fieldset v-if="supervisor" class="full"><legend>Control horari</legend><div class="form-grid"><label>Codi de fitxatge<input v-model="form.time_clock_code" maxlength="40" pattern="[A-Za-z0-9._-]+"></label><label>Treballadors relacionats amb<select v-model="form.parent_user_id"><option :value="null">Cap usuari pare</option><option v-for="u in users.filter(x=>x.is_active&&x.id!==editing?.id)" :key="u.id" :value="u.id">{{u.name}}</option></select></label><label class="check"><input v-model="form.multi_time_clock_enabled" type="checkbox"> Multifitxatge</label><label class="check"><input v-model="form.time_clock_day_night_columns_enabled" type="checkbox"> Veure columnes Dia i Nit</label><label class="check"><input v-model="form.time_clock_management_enabled" type="checkbox"> Gestió del control horari</label><label>Minuts ordinaris<input v-model.number="form.overtime_base_minutes" type="number" min="1" max="1440"></label><label>Llindar mitja hora<input v-model.number="form.overtime_half_threshold_minutes" type="number" min="0" max="59"></label><label>Llindar hora completa<input v-model.number="form.overtime_full_threshold_minutes" type="number" min="0" max="59"></label></div></fieldset></form><template #actions><button class="button secondary" @click="open=false">Cancel·lar</button><button form="user-form" class="button primary" :disabled="saving">{{saving?'Desant…':'Desar'}}</button></template></BaseModal></template>
